item.aggregated_output:
:root {
  font-family:'DM Sans',sans-serif;
  color:#eaf2e9;
  background:#101917;
  font-synthesis:none;
  text-rendering:optimizeLegibility;
  -webkit-font-smoothing:antialiased
}

* {
  box-sizing:border-box
}

body {
  margin:0;
  min-width:320px
}

button,input,select {
  font:inherit
}

button {
  cursor:pointer
}

button:focus-visible,input:focus-visible,select:focus-visible {
  outline:2px solid #b8ee80;
  outline-offset:3px
}

button:disabled {
  cursor:not-allowed
}

.app-shell {
  min-height:100vh;
  background:radial-gradient(circle at 82% 7%,rgba(97,132,83,.13),transparent 32%),#101917
}

.site-header {
  height:76px;
  border-bottom:1px solid #2b3833;
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:0 max(42px,calc((100vw - 1510px)/2));
  gap:20px
}

    min-height:39px;
    align-items:center;
    border-bottom:1px solid #29382e
  }
  .mobile-hour-label {
    font:600 10px 'Space Grotesk',sans-serif;
    color:#9cad9d
  }
  .current-mobile-row .mobile-hour-label {
    color:#c4ed9d
  }
  .mobile-hour-row .hour-cell {
    height:32px;
    font-size:10px
  }
  .grid-footer {
    padding:17px 14px 19px
  }
  .legend {
    gap:8px 13px
  }
  .legend>span {
    font-size:10px
  }
  .page-footer {
    padding:19px 2px;
    font-size:10px
  }
  .page-footer>span:last-child {
    display:none
  }
  .city-popover {
    right:-51px;
    width:min(310px,calc(100vw - 45px))
  }
  .settings-popover {
    right:0;
    width:min(288px,calc(100vw - 45px))
  }
}

@media(max-width:390px) {
  .intro-row h2 {
    font-size:35px
  }
  .header-right {
    font-size:0;
    gap:0
  }
  .live-dot {
    width:8px;
    height:8px
  }
  .add-button {
    font-size:0;
    width:40px;
    padding:0
  }
  .add-button svg {
    width:18px
  }
  .summary-text strong {
    font-size:17px
  }
}
